{% extends "base.html" %}
{% import "_macros.html" as macros %}

{% block title %}Flasky - Followers{% endblock %}

{% block page_content %}
<div class="page-header">
    <h2>{{ title }} {{ user.username }}</h2>
</div>
<div class="follows">
    <table class="table table-hover follows">
        <thead><tr><th></th><th>User</th><th>Since</th><th></th></tr></thead>
        {% for f in follows %}
        {% if f.user != user %}
        <tr>
            <td>
                <a href="{{ url_for('main.user', username=f.user.username) }}">
                    <img class="img-rounded" src="{{ f.user.gravatar(size=32) }}">
                </a>
            </td>
            <td>
                <a href="{{ url_for('main.user', username=f.user.username) }}">{{ f.user.username }}</a>
            </td>
            <td>{{ moment(f.timestamp).format('L') }}</td>
            <td>
                {% if current_user.is_authenticated and f.user != current_user %}
                    {% if f.user.is_followed_by(current_user) %}
                    <a href="{{ url_for('main.unfollow', username=f.user.username) }}">Unfollow</a>
                    {% else %}
                    <a href="{{ url_for('main.follow', username=f.user.username) }}">Follow</a>
                    {% endif %}
                {% endif %}
            </td>
        </tr>
        {% endif %}
        {% endfor %}
    </table>
</div>
{% if pagination %}
<div class="pagination">
    {{ macros.pagination_widget(pagination, endpoint) }}
</div>
{% endif %}
{% endblock %}

